rs contrasted with two carefully rewritten words.","caption":"Rewrite only the unclear parts and keep your hand comfortable.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Unclear copy</text><text x=\"28\" y=\"78\">merged letters</text><text x=\"358\" y=\"42\">Rewrite</text><text x=\"358\" y=\"78\">two clearer words</text></g></svg>"}],"year_level":"Year 3"}') WHERE seed_key='s2-eng-y3-w04-l4' AND family_id IS NULL;
